(() => {
  const bodyPs = [...document.querySelectorAll('[data-lexical-editor="true"] p')].map(p=>p.textContent);
  const allText = document.body.innerText;
  const occ = (allText.match(/fwgh7-n1 Bench Post/g)||[]).length;
  const bodyOcc = (document.querySelector('[data-lexical-editor="true"]')?.innerText.match(/fwgh7-n1/g)||[]).length;
  const tags = [...document.querySelectorAll('form[aria-label="Post settings"] .ember-power-select-multiple-option, form[aria-label="Post settings"] [data-testid="selected-tag"]')].map(e=>e.textContent.trim());
  const vis = document.querySelector('form[aria-label="Post settings"] select');
  return {
    bodyParagraphs: bodyPs,
    fwgh7_in_body_count: bodyOcc,
    fwgh7_in_title_count: occ,
    tagChips: tags,
    benchnl: allText.includes('Bench Newsletter'),
    visibility: vis ? vis.options[vis.selectedIndex].text : null,
    slug: document.querySelector('#url')?.value,
    date: document.querySelector('#date')?.value ?? [...document.querySelectorAll('input')].filter(i=>i.placeholder==='YYYY-MM-DD').map(i=>i.value),
    time: [...document.querySelectorAll('input')].filter(i=>/^\d{2}:\d{2}$/.test(i.value)).map(i=>i.value),
    excerpt: document.querySelector('#custom-excerpt')?.value,
    statusHeader: [...document.querySelectorAll('main header button, main header span')].map(e=>e.textContent.trim()).filter(Boolean)
  };
})()

(() => {
  const ps = [...document.querySelectorAll('[data-lexical-editor="true"] p')];
  const editors = [...document.querySelectorAll('[data-lexical-editor="true"]')];
  return {
    editorCount: editors.length,
    editors: editors.map(e=>({vis: e.offsetParent!==null, rect: e.getBoundingClientRect().height, cls: e.className.toString().slice(0,80)})),
    ps: ps.map(p=>({text:p.textContent, vis: p.offsetParent!==null, rectH: p.getBoundingClientRect().height, parentEditorIndex: editors.indexOf(p.closest('[data-lexical-editor="true"]'))})),
    visibleBodyText: editors.filter(e=>e.offsetParent!==null).map(e=>e.innerText)
  };
})()
